/*
 * Modified by Actuna Sp. z o.o.:
 *   #11: on close the node removes only its own routes (found by its handler,
 *   not by path and method, and without skipping a layer after a removed one),
 *   and the key of a raw body route stays while another node still uses it
 *   #8: a route with skipBodyParsing reads the raw body itself when the request
 *   bypassed rawBodyCapture (it arrived while the route of the node was being
 *   replaced and was held until the new flows started)
 *   #16: the raw body route fallback is used for every skipBodyParsing node, not only
 *   with deploy.holdHttpNodeRequests: a route with parameters or another letter case,
 *   which rawBodyCapture never matches, now gets a Buffer; the raw body is limited
 *   (apiMaxLength, or the "Max body size" of the node; 413 above it); rawBodyCapture
 *   is mounted on the httpNode app (behind httpNodeAuth and the hold of the requests,
 *   so nothing is read before the authentication) instead of the root app; the
 *   route reads the body with the limit of the node when the capture has not; the
 *   limit of the node also applies to the whole body of an upload
 *   #40: deploy.drainHttpNodeRequests - the handler of the route is marked and passes the request
 *   to the drain of the runtime (accepted); a request that the drain already answered with 503 is
 *   not sent into the flow, and "http response" does not answer it again
 *   #48: a text body above the maximum string length of Node.js is answered with 413; the limit given to the
 *   JSON and urlencoded parsers is at most that length; a 413 is not written to a request that another layer
 *   already answered
 *   #48: the optional httpInMaxBodySize setting is the default size limit of the raw body, of the whole body of
 *   an upload and of the other bodies that are not JSON or urlencoded; the "Max body size" of a node raises or
 *   lowers it; an invalid value is ignored with one warning; the editor gets only the flag httpInMaxBodySizeEnabled;
 *   a value shown in a warning (the setting, the limit of a node, apiMaxLength) is shown in a reduced form
 *   #48: an upload with a size limit (httpInMaxBodySize or the "Max body size" of the node) accepts at most 1000
 *   parts (fields and files together), more are answered with 413; a multipart field whose name has a number in
 *   brackets above 100 (for example a[101]) is answered with 413 on every upload route
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

module.exports = function(RED) {
    "use strict";
    var http = require("http");
    var bodyParser = require("body-parser");
    var multer = require("multer");
    var cookieParser = require("cookie-parser");
    var getBody = require('raw-body');
    var cors = require('cors');
    var onHeaders = require('on-headers');
    var typer = require('content-type');
    var mediaTyper = require('media-typer');
    var isUtf8 = require('is-utf8');
    var hashSum = require("hash-sum");
    // The contract of the drain of the HTTP requests (runtime/lib/httpDrain.js, #40): one symbol
    // that the runtime owns. On a handler of a route it is `true` (the route is drained); on
    // `req` and `res` it is the entry of the runtime, which exists only with
    // deploy.drainHttpNodeRequests enabled. The node never creates the entry.
    var DRAIN = Symbol.for("node-red.httpNode.drain");
    var DEFAULT_MAX_BODY_SIZE = 5 * 1024 * 1024;
    // The parts (fields and files together) of an upload with a size limit (#48). The parser
    // stops when the count reaches its option, so it gets one more to accept this many
    var MAX_UPLOAD_PARTS = 1000;
    // The largest number in brackets in the name of a multipart field (#48)
    var MAX_FIELD_ARRAY_INDEX = 100;
    var SIZE_UNITS = { b: 1, kb: 1024, mb: Math.pow(1024, 2), gb: Math.pow(1024, 3), tb: Math.pow(1024, 4), pb: Math.pow(1024, 5) };
    // A size is a short text: the limit also keeps the pattern below cheap to match
    var MAX_SIZE_TEXT_LENGTH = 32;
    // The maximum string length of Node.js: the largest text body that is read as a string (#48)
    var MAX_TEXT_BODY = require("buffer").constants.MAX_STRING_LENGTH;

    /**
     * The size in bytes that the JSON and urlencoded body parsers take from their `limit`
     * option, by the rules of the size parser they use (the `bytes` module): a number
     * that is not NaN as it is; a string of a number with a unit (kb, mb, gb, tb, pb;
     * 1024 based; an optional sign, spaces before the unit), otherwise the leading
     * integer of the string, as bytes; null for anything else.
     * @param {*} value
     * @returns {number|null}
     */
    function bodyParserLimitBytes(value) {
        if (typeof value === "number") {
            return isNaN(value) ? null : value;
        }
        if (typeof value !== "string") { return null; }
        var withUnit = /^([-+]?\d+(?:\.\d+)?) *(kb|mb|gb|tb|pb)$/i.exec(value);
        var amount = withUnit ? parseFloat(withUnit[1]) : parseInt(value, 10);
        if (isNaN(amount)) { return null; }
        var unit = withUnit ? SIZE_UNITS[withUnit[2].toLowerCase()] : 1;
        return Math.floor(unit * amount);
    }

    /**
     * The `limit` option of the JSON and urlencoded parsers: the given value, or the
     * maximum string length when the value gives a larger size (#48). Any other value
     * is passed unchanged, so the parsers treat it as before.
     * @param {*} value
     * @returns {*}
     */
    function bodyParserLimit(value) {
        var size = bodyParserLimitBytes(value);
        return (typeof size === "number" && size > MAX_TEXT_BODY) ? MAX_TEXT_BODY : value;
    }

    /**
     * Whether another layer already answered the request (or its response cannot be
     * written): then nothing more is written to it (#48)
     * @param {import('http').ServerResponse} res
     * @returns {boolean}
     */
    function responseSent(res) {
        return !!(res.headersSent || res.writableEnded || res.destroyed);
    }

    /**
     * Parses a size: a number of bytes, or a string with an optional unit (b, kb,
     * mb, gb, tb, pb; 1024 based, like the limit of the body parsers), for example "5mb".
     * @param {number|string} value
     * @returns {number|null} the size in bytes, or null when it is not a size above 0
     */
    function parseSize(value) {
        var size = null;
        if (typeof value === "number") {
            size = value;
        } else if (typeof value === "string") {
            var text = value.trim();
            var match = text.length <= MAX_SIZE_TEXT_LENGTH && /^(\d+(?:\.\d+)?)\s*(b|kb|mb|gb|tb|pb)?$/i.exec(text);
            if (match) {
                size = parseFloat(match[1]) * SIZE_UNITS[(match[2] || "b").toLowerCase()];
            }
        }
        if (typeof size !== "number" || !isFinite(size)) { return null; }
        size = Math.floor(size);
        return size > 0 ? size : null;
    }

    // Route keys (METHOD:url) of the nodes with skipBodyParsing, with the raw body size
    // limit of each node that uses the key (one entry per node): the key is removed when
    // the last of them closes (#11)
    var rawDataRoutes = new Map();

    function holdRawDataRoute(key, limit) {
        var limits = rawDataRoutes.get(key);
        if (!limits) {
            limits = [];
            rawDataRoutes.set(key, limits);
        }
        limits.push(limit);
    }

    function releaseRawDataRoute(key, limit) {
        var limits = rawDataRoutes.get(key);
        if (!limits) { return; }
        var index = limits.indexOf(limit);
        if (index >= 0) { limits.splice(index, 1); }
        if (limits.length === 0) { rawDataRoutes.delete(key); }
    }

    /**
     * Removes from the router of the app the routes (layers) that belong to one node:
     * the ones whose handlers include the callback of the node, which no other node
     * shares. The routes of other nodes on the same path and method stay. The stack is
     * changed in place (Express keeps the array), from the end, so that no layer is
     * skipped after a removed one. Without a router (no route was ever registered)
     * there is nothing to remove.
     * @param {import('express').Application} app
     * @param {Function} callback the handler registered by the node
     */
    function removeNodeRoutes(app, callback) {
        var router = app && app._router;
        if (!router || !Array.isArray(router.stack)) { return; }
        for (var i = router.stack.length - 1; i >= 0; i--) {
            var route = router.stack[i].route;
            if (route && Array.isArray(route.stack) && route.stack.some(function(l) { return l.handle === callback; })) {
                router.stack.splice(i, 1);
            }
        }
    }

    // How much of the rest of a rejected body is read and discarded before the answer
    var MAX_DISCARDED_BODY = 64 * 1024 * 1024;

    /**
     * Answers 413 (a body above the limit). Plain Node.js calls, no Express helpers.
     * The rest of the request is read and discarded first: a client that is still
     * sending when the server answers sees a reset connection instead of the 413.
     * When the declared Content-Length is above MAX_DISCARDED_BODY, or the discarded
     * part passes it, the answer is sent at once and the connection is closed
     * instead of reading more. A response that another layer already sent (or sends
     * while the rest is discarded) is left as it is (#48).
     * @param {import('http').IncomingMessage} req
     * @param {import('http').ServerResponse} res
     */
    function sendTooLarge(req, res) {
        if (responseSent(res)) { return; }
        var answered = false;
        var discarded = 0;
        function answer(closeConnection) {
            if (answered) { return; }
            answered = true;
            if (responseSent(res)) { return; }
            var text = http.STATUS_CODES[413];
            res.statusCode = 413;
            res.setHeader("Content-Type", "text/plain; charset=utf-8");
            res.setHeader("Content-Length", Buffer.byteLength(text));
            if (closeConnection) {
                res.setHeader("Connection", "close");
            }
            res.end(text);
        }
        if (req.complete || req.readableEnded) { return answer(false); }
        if (parseInt(req.headers["content-length"], 10) > MAX_DISCARDED_BODY) { return answer(true); }
        req.on("data", function(chunk) {
            discarded += chunk.length;
            if (discarded > MAX_DISCARDED_BODY) { answer(true); }
        });
        req.on("end", function() { answer(false) });
        // an aborted request: the answer goes nowhere, but it ends the response
        req.on("error", function() { answer(false) });
        req.on("close", function() { answer(false) });
        req.resume();
    }

    /**
     * Creates the parser of the bodies that are not JSON, URL-encoded or multipart
     * (the last parser of a route). A text body is limited to the maximum string
     * length, or to `limit` when it is lower; a binary body only to `limit` (#48).
     * @param {number|null} limit the largest accepted body in bytes, or null for none
     * @returns {import('express').RequestHandler}
     */
    function createRawBodyParser(limit) {
        var textLimit = limit ? Math.min(limit, MAX_TEXT_BODY) : MAX_TEXT_BODY;
        var binaryLimit = limit || undefined;
        return function rawBodyParser(req, res, next) {
            parseRawBody(req, res, next, textLimit, binaryLimit);
        };
    }

    function parseRawBody(req, res, next, textLimit, binaryLimit) {
        if (req.skipRawBodyParser || req._body || req.readableEnded) return next();
        
        req.body = "";
        req._body = true;

        var isText = true;
        var checkUTF = false;

        if (req.headers['content-type']) {
            var contentType = typer.parse(req.headers['content-type'])
            if (contentType.type) {
                var parsedType = mediaTyper.parse(contentType.type);
                if (parsedType.type === "text") {
                    isText = true;
                } else if (parsedType.subtype === "xml" || parsedType.suffix === "xml") {
                    isText = true;
                } else if (parsedType.type !== "application") {
                    isText = false;
                } else if ((parsedType.subtype !== "octet-stream")
                    && (parsedType.subtype !== "cbor")
                    && (parsedType.subtype !== "x-protobuf")) {
                    checkUTF = true;
                } else {
                    // application/octet-stream or application/cbor
                    isText = false;
                }

            }
        }

        // A text body is limited to the maximum string length (#48); a binary body has no
        // limit unless the route has one (httpInMaxBodySize, #48)
        getBody(req, {
            length: req.headers['content-length'],
            encoding: isText ? "utf8" : null,
            limit: isText ? textLimit : binaryLimit
        }, function (err, buf) {
            if (err) {
                if (err.type === "entity.too.large") { return sendTooLarge(req, res); }
                return next(err);
            }
            if (!isText && checkUTF && isUtf8(buf)) {
                buf = buf.toString()
            }
            req.body = buf;
            next();
        });
    }

    /**
     * It provide the unique route key
     * @param {{method: string, url: string}} obj 
     * @returns 
     */
    function getRouteKey(obj) {
        var method = obj.method.toUpperCase();
        // Normalize the URL by replacing double slashes with a single slash and removing the trailing slash
        var url = obj.url.replace(/\/{2,}/g, '/').replace(/\/$/, '');
        return `${method}:${url}`;
    }

    /**
     * This middleware is for capture raw body: it reads the body of a request for the
     * route of a node with skipBodyParsing, so that the middleware and the routes that
     * follow (httpNodeMiddleware, other routes) find a Buffer in req.body. It is
     * mounted on the httpNode app (not on the root app), so it runs behind the
     * authentication of the nodes (httpNodeAuth) and the hold of the requests, and
     * nothing is read before the request is authenticated (#16). The capture does not
     * know which node answers, so it reads up to the highest limit of the nodes on the
     * key; the route of each node checks its own limit (rawBodyFallback). A body above
     * that limit is answered with 413 here (with the CORS headers), whoever would
     * answer the request.
     * @param {import('express').Request} req
     * @param {import('express').Response} res
     * @param {import('express').NextFunction} next
     * @returns
     */
    function rawBodyCapture(req, res, next) {
        // The app is mounted on httpNodeRoot, so the url is relative to it, as the paths of the nodes
        var routeKey = getRouteKey({ method: req.method, url: req._parsedUrl.pathname });
        // Check if routeKey exist in rawDataRoutes
        var limits = rawDataRoutes.get(routeKey);
        if (limits) {
            readRawBody(req, res, Math.max.apply(null, limits), next, true);
        } else {
            next();
        }
    }

    /**
     * Converts the request stream to a Buffer in req.body and marks the body as
     * read, so that the body parsers of the route skip it. A body above the limit
     * is answered with 413 (#16); with `withCors` (the capture, which runs before the
     * route and its CORS handler) the CORS headers of the nodes are set first.
     * Nothing else gets the request: whoever would answer it would wait for a body
     * that raw-body stopped reading.
     * @param {import('express').Request} req
     * @param {import('express').Response} res
     * @param {number} limit the largest accepted body in bytes
     * @param {import('express').NextFunction} next
     * @param {boolean} [withCors]
     */
    function readRawBody(req, res, limit, next, withCors) {
        getBody(req, {
            length: req.headers['content-length'],
            limit: limit
        }, function (err, buf) {
            if (err) {
                if (err.type === "entity.too.large") {
                    // another layer already answered: no headers are set (#48)
                    if (responseSent(res)) { return; }
                    if (withCors) {
                        return corsHandler(req, res, function() { sendTooLarge(req, res) });
                    }
                    return sendTooLarge(req, res);
                }
                return next(err);
            }
            req.body = buf;
            // Skip the body parsing
            req.skipRawBodyParser = true;
            req._rawBodyRead = true;
            req._body = true;
            next();
        })
    }

    /**
     * Creates the step of the route of a node with skipBodyParsing that gives the
     * handler the raw body (a Buffer) within the limit of the node. It reads the body
     * when rawBodyCapture has not: rawBodyCapture matches the literal `METHOD:url`, so
     * a route with parameters (`/hook/:id`) or another letter case is never captured
     * (#16), and a request that arrives between the close of the old node (its key
     * leaves rawDataRoutes) and the start of the new one passes it unread (#8). The
     * flags `skipRawBodyParser` and `_body` do not tell that the body was read (a
     * middleware may set them to skip the parsers, as the settings template shows), so
     * the step reads the body unless the capture did (`_rawBodyRead`) or the stream
     * was consumed by someone else. When the capture read the body, only its size is
     * checked against the limit of this node, which may be lower than the one the
     * capture used.
     * @param {number} limit the largest accepted body in bytes
     * @returns {import('express').RequestHandler}
     */
    function createRawBodyFallback(limit) {
        return function rawBodyFallback(req, res, next) {
            if (req._rawBodyRead) {
                if (Buffer.isBuffer(req.body) && req.body.length > limit) {
                    return sendTooLarge(req, res);
                }
                return next();
            }
            if (req.readableEnded) return next();
            readRawBody(req, res, limit, next);
        };
    }

    if (typeof RED.httpNode === 'function') {
        // Mounted on the httpNode app when the module loads: behind what the runtime put
        // there first (the hold of the requests, #8) and in front of the routes of the nodes.
        // A capture of an earlier load of the module (RED.stop() and RED.start() in one
        // process load it again, with an empty set of keys) is replaced at its place.
        rawBodyCapture.isRawBodyCapture = true;
        var captureStack = RED.httpNode._router && RED.httpNode._router.stack;
        var captureAt = -1;
        if (Array.isArray(captureStack)) {
            for (var ci = captureStack.length - 1; ci >= 0; ci--) {
                if (captureStack[ci].handle && captureStack[ci].handle.isRawBodyCapture) {
                    captureAt = ci;
                    captureStack.splice(ci, 1);
                }
            }
        }
        RED.httpNode.use(rawBodyCapture);
        if (captureAt >= 0) {
            var added = RED.httpNode._router.stack;
            added.splice(captureAt, 0, added.pop());
        }
    }

    function createRequestWrapper(node,req) {
        // This misses a bunch of properties (eg headers). Before we use this function
        // need to ensure it captures everything documented by Express and HTTP modules.
        var wrapper = {
            _req: req
        };
        var toWrap = [
            "param",
            "get",
            "is",
            "acceptsCharset",
            "acceptsLanguage",
            "app",
            "baseUrl",
            "body",
            "cookies",
            "fresh",
            "hostname",
            "ip",
            "ips",
            "originalUrl",
            "params",
            "path",
            "protocol",
            "query",
            "route",
            "secure",
            "signedCookies",
            "stale",
            "subdomains",
            "xhr",
            "socket" // TODO: tidy this up
        ];
        toWrap.forEach(function(f) {
            if (typeof req[f] === "function") {
                wrapper[f] = function() {
                    node.warn(RED._("httpin.errors.deprecated-call",{method:"msg.req."+f}));
                    var result = req[f].apply(req,arguments);
                    if (result === req) {
                        return wrapper;
                    } else {
                        return result;
                    }
                }
            } else {
                wrapper[f] = req[f];
            }
        });


        return wrapper;
    }

    function createResponseWrapper(node,res) {
        var wrapper = {
            _res: res
        };
        var toWrap = [
            "append",
            "attachment",
            "cookie",
            "clearCookie",
            "download",
            "end",
            "format",
            "get",
            "json",
            "jsonp",
            "links",
            "location",
            "redirect",
            "render",
            "send",
            "sendfile",
            "sendFile",
            "sendStatus",
            "set",
            "status",
            "type",
            "vary"
        ];
        toWrap.forEach(function(f) {
            wrapper[f] = function() {
                node.warn(RED._("httpin.errors.deprecated-call",{method:"msg.res."+f}));
                var result = res[f].apply(res,arguments);
                if (result === res) {
                    return wrapper;
                } else {
                    return result;
                }
            }
        });
        return wrapper;
    }

    var corsHandler = function(req,res,next) { next(); }

    if (RED.settings.httpNodeCors) {
        corsHandler = cors(RED.settings.httpNodeCors);
        RED.httpNode.options("*",corsHandler);
    }

    /**
     * A value of a setting or of a node as a warning shows it (#48): a string cut to
     * MAX_SIZE_TEXT_LENGTH characters, with every character other than a letter, a digit,
     * a space, ".", "+" or "-" replaced by "?"; a number as it is; any other value only
     * as its type, so that showing it calls nothing on it
     * @param {*} value
     * @returns {string|number}
     */
    function shownValue(value) {
        if (typeof value === "string") {
            return value.slice(0, MAX_SIZE_TEXT_LENGTH).replace(/[^0-9A-Za-z .+-]/g, "?");
        }
        if (typeof value === "number") { return value; }
        return typeof value;
    }

    var warnedApiMaxLength = false;

    /**
     * The default limit of the raw body: the apiMaxLength setting, the same as for the
     * JSON and urlencoded parsers (5mb by default). A value that is not a size above 0
     * (the body parsers accept a number of 0 or less) logs one warning and uses 5mb.
     * @returns {number} bytes
     */
    function apiMaxLength() {
        if (!RED.settings.apiMaxLength) { return DEFAULT_MAX_BODY_SIZE; }
        var size = parseSize(RED.settings.apiMaxLength);
        if (size === null) {
            if (!warnedApiMaxLength) {
                warnedApiMaxLength = true;
                RED.log.warn(RED._("httpin.errors.invalid-api-max-length", {value: shownValue(RED.settings.apiMaxLength)}));
            }
            return DEFAULT_MAX_BODY_SIZE;
        }
        return size;
    }

    // The default size limit of the bodies of the routes (#48): the httpInMaxBodySize
    // setting, read once when the module loads. Not set (or falsy): no default limit, as
    // before. A value that is not a size above 0, or that cannot be read (shown as "?"),
    // is ignored with one warning.
    var defaultBodyLimit = null;
    var defaultBodyLimitText = null;
    (function readDefaultBodyLimit() {
        var value;
        try {
            value = RED.settings.httpInMaxBodySize;
        } catch (err) {
            RED.log.warn(RED._("httpin.errors.invalid-max-body-size-setting", {value: "?"}));
            return;
        }
        if (!value) { return; }
        var size = parseSize(value);
        if (size === null) {
            RED.log.warn(RED._("httpin.errors.invalid-max-body-size-setting", {value: shownValue(value)}));
            return;
        }
        defaultBodyLimit = size;
        defaultBodyLimitText = shownValue(typeof value === "string" ? value.trim() : value);
        if (size > MAX_TEXT_BODY) {
            RED.log.warn(RED._("httpin.errors.large-max-body-size-setting", {value: defaultBodyLimitText}));
        }
    })();

    function HTTPIn(n) {
        RED.nodes.createNode(this,n);
        if (RED.settings.httpNodeRoot !== false) {

            if (!n.url) {
                this.warn(RED._("httpin.errors.missing-path"));
                return;
            }
            this.url = n.url;
            if (this.url[0] !== '/') {
                this.url = '/'+this.url;
            }
            this.method = n.method;
            this.upload = n.upload;
            this.skipBodyParsing = n.skipBodyParsing;
            this.swaggerDoc = n.swaggerDoc;

            var node = this;
            var routeKey = getRouteKey({method: this.method, url: this.url});

            this.errorHandler = function(err,req,res,next) {
                // #40: the request was answered by the drain (503), the error is of no use
                if (req[DRAIN] && req[DRAIN].drained) { return; }
                node.warn(err);
                res.sendStatus(500);
            };

            this.callback = function(req,res) {
                // #40: the request was answered by the drain (503) while its body was read: nothing is sent
                var drainEntry = req[DRAIN];
                if (drainEntry) {
                    if (drainEntry.drained) { return; }
                    drainEntry.accepted = true;
                }
                var msgid = RED.util.generateId();
                res._msgid = msgid;
                // Since Node 15, req.headers are lazily computed and the property
                // marked as non-enumerable.
                // That means it doesn't show up in the Debug sidebar.
                // This redefines the property causing it to be evaluated *and*
                // marked as enumerable again.
                Object.defineProperty(req, 'headers', {
                    value: req.headers,
                    enumerable: true
                })
                if (node.method.match(/^(post|delete|put|options|patch)$/)) {
                    node.send({_msgid:msgid,req:req,res:createResponseWrapper(node,res),payload:req.body});
                } else if (node.method == "get") {
                    node.send({_msgid:msgid,req:req,res:createResponseWrapper(node,res),payload:req.query});
                } else {
                    node.send({_msgid:msgid,req:req,res:createResponseWrapper(node,res)});
                }
            };

            // #40: marks the route as one that the drain of the runtime answers
            this.callback[DRAIN] = true;

            var httpMiddleware = function(req,res,next) { next(); }

            if (RED.settings.httpNodeMiddleware) {
                if (typeof RED.settings.httpNodeMiddleware === "function" || Array.isArray(RED.settings.httpNodeMiddleware)) {
                    httpMiddleware = RED.settings.httpNodeMiddleware;
                }
            }

            // The JSON and urlencoded parsers read the body as text: their limit is at most the
            // maximum string length (#48)
            var maxApiRequestSize = bodyParserLimit(RED.settings.apiMaxLength || '5mb');

            // The size limit of the raw body (skipBodyParsing) and of the whole body of an
            // upload (#16). The limit of the node is optional; the raw body is also limited
            // without it, by the httpInMaxBodySize setting when it is set (#48), otherwise by
            // the same setting as the JSON and urlencoded parsers. With httpInMaxBodySize set
            // the limit of the node also replaces it for the other bodies of a route of a
            // method with a body (#48)
            var nodeLimit = null;
            var rawLimit = null;
            var bodyMethod = /^(post|put|patch|delete)$/.test(this.method);
            if (this.skipBodyParsing || this.upload || (defaultBodyLimit && bodyMethod)) {
                if (typeof n.maxBodySize === "number" || (typeof n.maxBodySize === "string" && n.maxBodySize.trim() !== "")) {
                    var nodeLimitText = shownValue(n.maxBodySize);
                    nodeLimit = parseSize(n.maxBodySize);
                    if (nodeLimit === null) {
                        this.warn(RED._("httpin.errors.invalid-max-body-size", {value: nodeLimitText}));
                    } else {
                        if (nodeLimit > MAX_TEXT_BODY) {
                            this.warn(RED._("httpin.errors.large-max-body-size", {value: nodeLimitText}));
                        }
                        if (defaultBodyLimit && nodeLimit > defaultBodyLimit) {
                            this.warn(RED._("httpin.errors.max-body-size-above-default", {value: nodeLimitText, default: defaultBodyLimitText}));
                        }
                    }
                }
                rawLimit = nodeLimit || defaultBodyLimit || apiMaxLength();
            }
            // The limit of the other bodies (not JSON, urlencoded or multipart): only with the
            // httpInMaxBodySize setting (#48)
            var rawBodyParser = createRawBodyParser(defaultBodyLimit ? (nodeLimit || defaultBodyLimit) : null);
            // The limit of the whole body of an upload: without both limits it is not limited
            var uploadLimit = nodeLimit || defaultBodyLimit;

            var rawFallback = function(req,res,next) { next(); };
            if (this.skipBodyParsing) {
                rawFallback = createRawBodyFallback(rawLimit);
            }

            var jsonParser = bodyParser.json({limit:maxApiRequestSize});

            var urlencParser = bodyParser.urlencoded({limit:maxApiRequestSize,extended:true});

            var metricsHandler = function(req,res,next) { next(); }
            if (this.metric()) {
                metricsHandler = function(req, res, next) {
                    var startAt = process.hrtime();
                    onHeaders(res, function() {
                        if (res._msgid) {
                            var diff = process.hrtime(startAt);
                            var ms = diff[0] * 1e3 + diff[1] * 1e-6;
                            var metricResponseTime = ms.toFixed(3);
                            var metricContentLength = res.getHeader("content-length");
                            //assuming that _id has been set for res._metrics in HttpOut node!
                            node.metric("response.time.millis", {_msgid:res._msgid} , metricResponseTime);
                            node.metric("response.content-length.bytes", {_msgid:res._msgid} , metricContentLength);
                        }
                    });
                    next();
                };
            }

            var multipartParser = function(req,res,next) { next(); }
            if (this.upload) {
                // Without the limit of the node (or the httpInMaxBodySize setting, #48) the
                // upload is not limited, as before. With it the number of parts is limited too;
                // a number in brackets in the name of a field is always limited (#48)
                var uploadPartLimits = { fieldArrayIndexLimit: MAX_FIELD_ARRAY_INDEX };
                if (uploadLimit) {
                    uploadPartLimits.parts = MAX_UPLOAD_PARTS + 1;
                }
                var mp = multer({ storage: multer.memoryStorage(), limits: uploadPartLimits }).any();
                multipartParser = function(req,res,next) {
                    if(req.readableEnded || req._body) return next();
                    var limited = uploadLimit && /^multipart\//i.test(req.headers["content-type"] || "");
                    var settled = false;
                    var received = 0;
                    function count(chunk) {
                        received += chunk.length;
                        if (received > uploadLimit && !settled) {
                            // the whole body (files and fields) is above the limit: multer
                            // gets no more of it, the rest is discarded and the answer is 413
                            settled = true;
                            req.removeListener("data", count);
                            req.unpipe();
                            sendTooLarge(req, res);
                        }
                    }
                    if (limited) {
                        if (parseInt(req.headers["content-length"], 10) > uploadLimit) {
                            req._body = true;
                            return sendTooLarge(req, res);
                        }
                        // listening for data only after the checks above, together with
                        // the pipe of multer in the same tick (the body is not lost)
                        req.on("data", count);
                    }
                    mp(req,res,function(err) {
                        if (limited) { req.removeListener("data", count); }
                        if (settled) { return; }
                        settled = true;
                        req._body = true;
                        // too many parts, or a number in a field name above the limit: 413 (#48);
                        // any other error of the parser takes the error handler, as before
                        if (err instanceof multer.MulterError && (err.code === "LIMIT_PART_COUNT" || err.code === "LIMIT_FIELD_ARRAY_INDEX")) {
                            return sendTooLarge(req, res);
                        }
                        next(err);
                    })
                };
            }

            if (this.method == "get") {
                RED.httpNode.get(this.url, cookieParser(), httpMiddleware, corsHandler, metricsHandler, this.callback, this.errorHandler);
            } else if (this.method == "post") {
                RED.httpNode.post(this.url,cookieParser(), httpMiddleware, corsHandler, metricsHandler, rawFallback, jsonParser, urlencParser, multipartParser, rawBodyParser, this.callback, this.errorHandler);
            } else if (this.method == "put") {
                RED.httpNode.put(this.url, cookieParser(), httpMiddleware, corsHandler, metricsHandler, rawFallback, jsonParser, urlencParser, rawBodyParser, this.callback, this.errorHandler);
            } else if (this.method == "patch") {
                RED.httpNode.patch(this.url, cookieParser(), httpMiddleware, corsHandler, metricsHandler, rawFallback, jsonParser, urlencParser, rawBodyParser, this.callback, this.errorHandler);
            } else if (this.method == "delete") {
                RED.httpNode.delete(this.url, cookieParser(), httpMiddleware, corsHandler, metricsHandler, rawFallback, jsonParser, urlencParser, rawBodyParser, this.callback, this.errorHandler);
            }

            // If the user enables raw body, add it to the raw data routes. Only after the
            // route was registered (an invalid path throws above) and just before the close
            // listener that releases the key, so a failed start never leaves it held.
            var rawKeyHeld = false;
            if(this.skipBodyParsing) {
                rawKeyHeld = true;
                holdRawDataRoute(routeKey, rawLimit);
            }

            this.on("close",function() {
                // Release the raw data route key of this node (the key stays while
                // another node still uses the same route key)
                if (rawKeyHeld) {
                    rawKeyHeld = false;
                    releaseRawDataRoute(routeKey, rawLimit);
                }
                // Remove only the routes this node registered
                removeNodeRoutes(RED.httpNode, node.callback);
            });
        } else {
            this.warn(RED._("httpin.errors.not-created"));
        }
    }
    
    // The editor shows the "Max body size" of every route of a method with a body when the
    // httpInMaxBodySize setting is in use (#48). Only this flag is given to the editor, never
    // the value of the setting. An empty set replaces the flag of an earlier load of the module.
    RED.nodes.registerType("http in",HTTPIn,{
        settings: defaultBodyLimit ? { httpInMaxBodySizeEnabled: { value: true, exportable: true } } : {}
    });

    function HTTPOut(n) {
        RED.nodes.createNode(this,n);
        var node = this;
        this.headers = n.headers||{};
        this.statusCode = parseInt(n.statusCode);
        this.on("input",function(msg,_send,done) {
            if (msg.res) {
                // #40: the request was answered by the drain (503): a late response is dropped
                var drainEntry = msg.res._res && msg.res._res[DRAIN];
                if (drainEntry && drainEntry.drained) {
                    node.debug(RED._("httpin.errors.drained-response"));
                    done();
                    return;
                }
                var headers = RED.util.cloneMessage(node.headers);
                if (msg.headers) {
                    if (msg.headers.hasOwnProperty('x-node-red-request-node')) {
                        var headerHash = msg.headers['x-node-red-request-node'];
                        delete msg.headers['x-node-red-request-node'];
                        var hash = hashSum(msg.headers);
                        if (hash === headerHash) {
                            delete msg.headers;
                        }
                    }
                    if (msg.headers) {
                        for (var h in msg.headers) {
                            if (msg.headers.hasOwnProperty(h) && !headers.hasOwnProperty(h)) {
                                headers[h] = msg.headers[h];
                            }
                        }
                    }
                }
                if (Object.keys(headers).length > 0) {
                    msg.res._res.set(headers);
                }
                if (msg.cookies) {
                    for (var name in msg.cookies) {
                        if (msg.cookies.hasOwnProperty(name)) {
                            if (msg.cookies[name] === null || msg.cookies[name].value === null) {
                                if (msg.cookies[name]!==null) {
                                    msg.res._res.clearCookie(name,msg.cookies[name]);
                                } else {
                                    msg.res._res.clearCookie(name);
                                }
                            } else if (typeof msg.cookies[name] === 'object') {
                                msg.res._res.cookie(name,msg.cookies[name].value,msg.cookies[name]);
                            } else {
                                msg.res._res.cookie(name,msg.cookies[name]);
                            }
                        }
                    }
                }
                var statusCode = node.statusCode || parseInt(msg.statusCode) || 200;
                if (typeof msg.payload == "object" && !Buffer.isBuffer(msg.payload)) {
                    msg.res._res.status(statusCode).jsonp(msg.payload);
                } else {
                    if (msg.res._res.get('content-length') == null) {
                        var len;
                        if (msg.payload == null) {
                            len = 0;
                        } else if (Buffer.isBuffer(msg.payload)) {
                            len = msg.payload.length;
                        } else if (typeof msg.payload == "number") {
                            len = Buffer.byteLength(""+msg.payload);
                        } else {
                            len = Buffer.byteLength(msg.payload);
                        }
                        msg.res._res.set('content-length', len);
                    }

                    if (typeof msg.payload === "number") {
                        msg.payload = ""+msg.payload;
                    }
                    msg.res._res.status(statusCode).send(msg.payload);
                }
            } else {
                node.warn(RED._("httpin.errors.no-response"));
            }
            done();
        });
    }

    RED.nodes.registerType("http response",HTTPOut);
}
